[{"order":1,"type":"heading","text":"Node.js CRUD Operations: A Comprehensive Guide"},{"order":2,"type":"paragraph","text":"This tutorial provides a practical guide to performing CRUD (Create, Read, Update, Delete) operations in Node.js. We'll cover the fundamental concepts and demonstrate how to implement these operations using a database (e.g., MongoDB) and a popular Node.js ORM (e.g., Mongoose)."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Node.js and npm installed on your system."},{"order":5,"type":"bullet_point","text":"Basic understanding of JavaScript and asynchronous programming (Promises, async/await)."},{"order":6,"type":"bullet_point","text":"A MongoDB database instance running locally or remotely."},{"order":7,"type":"bullet_point","text":"Familiarity with command-line interface (CLI)."},{"order":8,"type":"subheading","text":"Setting up the Project"},{"order":9,"type":"paragraph","text":"First, create a new directory for your project and initialize a Node.js project:"},{"order":10,"type":"code","text":"mkdir node-crud-example
cd node-crud-example
npm init -y"},{"order":11,"type":"paragraph","text":"Next, install the necessary dependencies. We'll use Mongoose to interact with MongoDB and Express.js to create a simple API:"},{"order":12,"type":"code","text":"npm install express mongoose body-parser"},{"order":13,"type":"subheading","text":"Connecting to MongoDB"},{"order":14,"type":"paragraph","text":"Create a file named 'app.js' and add the following code to connect to your MongoDB database:"},{"order":15,"type":"code","text":"const express = require('express');
const mongoose = require('mongoose');
const bodyParser = require('body-parser');

const app = express();
const port = 3000;

// Middleware
app.use(bodyParser.json());

// MongoDB Connection
mongoose.connect('mongodb://localhost:27017/node-crud', { useNewUrlParser: true, useUnifiedTopology: true })
  .then(() => console.log('Connected to MongoDB'))
  .catch(err => console.error('MongoDB connection error:', err));

app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});"},{"order":16,"type":"subheading","text":"Defining a Mongoose Schema and Model"},{"order":17,"type":"paragraph","text":"Define a schema for your data. For example, let's create a 'Product' model:"},{"order":18,"type":"code","text":"const productSchema = new mongoose.Schema({
  name: { type: String, required: true },
  description: String,
  price: { type: Number, required: true },
  createdAt: { type: Date, default: Date.now }
});

const Product = mongoose.model('Product', productSchema);"},{"order":19,"type":"subheading","text":"Create (POST)"},{"order":20,"type":"paragraph","text":"Implement the 'Create' operation to add new products to the database:"},{"order":21,"type":"code","text":"app.post('/products', async (req, res) => {
  try {
    const product = new Product(req.body);
    const savedProduct = await product.save();
    res.status(201).json(savedProduct);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});"},{"order":22,"type":"subheading","text":"Read (GET)"},{"order":23,"type":"paragraph","text":"Implement the 'Read' operation to retrieve products from the database:"},{"order":24,"type":"code","text":"// Get all products
app.get('/products', async (req, res) => {
  try {
    const products = await Product.find();
    res.json(products);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// Get a single product by ID
app.get('/products/:id', async (req, res) => {
  try {
    const product = await Product.findById(req.params.id);
    if (!product) {
      return res.status(404).json({ message: 'Product not found' });
    }
    res.json(product);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});"},{"order":25,"type":"subheading","text":"Update (PUT/PATCH)"},{"order":26,"type":"paragraph","text":"Implement the 'Update' operation to modify existing products:"},{"order":27,"type":"code","text":"app.put('/products/:id', async (req, res) => {
  try {
    const product = await Product.findByIdAndUpdate(req.params.id, req.body, { new: true });
    if (!product) {
      return res.status(404).json({ message: 'Product not found' });
    }
    res.json(product);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});"},{"order":28,"type":"subheading","text":"Delete (DELETE)"},{"order":29,"type":"paragraph","text":"Implement the 'Delete' operation to remove products from the database:"},{"order":30,"type":"code","text":"app.delete('/products/:id', async (req, res) => {
  try {
    const product = await Product.findByIdAndDelete(req.params.id);
    if (!product) {
      return res.status(404).json({ message: 'Product not found' });
    }
    res.json({ message: 'Product deleted' });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});"},{"order":31,"type":"subheading","text":"Running the Application"},{"order":32,"type":"paragraph","text":"Start the Node.js server:"},{"order":33,"type":"code","text":"node app.js"},{"order":34,"type":"paragraph","text":"You can now test the API endpoints using tools like Postman or curl."},{"order":35,"type":"subheading","text":"Conclusion"},{"order":36,"type":"paragraph","text":"This tutorial demonstrated how to implement CRUD operations in Node.js using Mongoose and MongoDB. You can extend this example by adding more features, such as validation, authentication, and authorization."}]
